from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3 import pages
from taf.selenium.sbts_fsm3.pages import v20b
from taf.selenium.sbts_fsm3.pages.modals import SynchronizeWithActivePartitionModal


class Software(v20b.Software):
    """
    The class corresponding to software page on selenium_sbts web, all operations under software
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Software, self).__init__(driver, download_checker)
        self._software_update = SoftwareUpdatePage(driver, download_checker)


class SoftwareUpdatePage(pages.software.SoftwareUpdatePage):

    def __init__(self, driver, download_checker):
        super(SoftwareUpdatePage, self).__init__(driver, download_checker)
        self._view_panel = SoftwareUpdatePageViewPanel(driver, download_checker)

    def synchronize(self, with_health_check=True, timeout=60):
        return self._view_panel.synchronize(with_health_check, timeout)


class SoftwareUpdatePageViewPanel(pages.software.SoftwareUpdatePageViewPanel):
    _SYNCHRONIZE_BUTTON = '//button[contains(text(), "Synchronize")]'

    def __init__(self, driver, download_checker):
        super(SoftwareUpdatePageViewPanel, self).__init__(driver, download_checker)

    def synchronize(self, with_health_check, timeout):
        self.click_enabled_element_after_visible((By.XPATH, self._SYNCHRONIZE_BUTTON), timeout)

        synchronize_with_active = SynchronizeWithActivePartitionModal(self.driver)
        synchronize_with_active.wait_until_synchronize_modal_appear(timeout)
        synchronize_with_active.health_check(with_health_check, timeout)
        synchronize_with_active.synchronize(timeout)
        return synchronize_with_active.wait_until_synchronize_completed(timeout)
